export function delayFor(response, attempt, baseMs) {
  const headers = response?.headers ?? {};
  const retryAfterName = Object.keys(headers).find(
    name => name.toLowerCase() === 'retry-after'
  );
  const retryAfter = retryAfterName === undefined ? undefined : headers[retryAfterName];

  if (
    (typeof retryAfter === 'number' ||
      (typeof retryAfter === 'string' && retryAfter.trim() !== '')) &&
    Number.isFinite(Number(retryAfter)) &&
    Number(retryAfter) >= 0
  ) {
    return Number(retryAfter) * 1000;
  }

  return baseMs * 2 ** (attempt - 1);
}

export function shouldRetry(response) {
  const status = response?.status;
  return status === 429 || (Number.isFinite(status) && status >= 500 && status < 600);
}
